from pathlib import Path
p=Path('index.html');s=p.read_text();s=s.replace('if (token "'!== request) return;'"\\n          image.hidden = true;', 'if (token "'!== request) return;'"\\n          setExpanded(false);\\n          image.hidden = true;');p.write_text(s)
